async def act(page):
    # Locate the table containing the Last 5 Orders data
    # Based on the accessibility tree, the table is within a group under a cell with name containing 'Last 5 Orders'
    # Use filtering to target the specific table
    table = page.get_by_role("cell", name="Last 5 Orders", exact=False).get_by_role("group").get_by_role("table")

    # Get all rows in the rowgroup that contain the order data (excluding the header row)
    # The header row has name 'Customer Items Grand Total', so we filter it out
    rows = table.get_by_role("rowgroup").last.get_by_role("row").filter(has_not=page.get_by_role("cell", name="Customer", exact=False))

    # Extract the item counts from the second cell of each row
    item_counts = []
    for i in range(await rows.count()):
        row = rows.nth(i)
        # Get the second cell (index 1) which contains the items count
        cell = row.get_by_role("cell").nth(1)
        text = await cell.text_content()
        # Convert to integer, assuming the text is a number
        try:
            count = int(text.strip())
            item_counts.append(count)
        except ValueError:
            # If conversion fails, skip or handle error, but based on tree, it should be numbers
            continue

    # Calculate the total
    total_items = sum(item_counts)

    # Return the total as the result
    return str(total_items)
